def intervalLocalizedExtension (φ : C(UnitInterval, ℝ)) (hφ : ∀ t, 0 ≤ φ t ∧ φ t ≤ 1)
    (E : C(K, 𝕜) →L[𝕜] IntervalContinuous 𝕜) : C(K, 𝕜) →L[𝕜] IntervalContinuous 𝕜 :=
  (continuousMapCutoff φ hφ).comp E

